('MICL Aaradhya OnePark', 'micl-aaradhya-onepark', 'MICL Group', 'Residential', 'Mumbai', '60ft Road, Ghatkopar East, Mumbai', '₹ 2.80 Cr Onwards', 28000000, 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80', '3, 4 & 5 BHK', 3, 5, 'Dec 2026', 'new-launch', 'Ultra Luxury High-Rise on 60ft Road', 'Aaradhya OnePark brings ultra-luxury living to the prestigious 60ft Road in Ghatkopar East. A perfect blend of contemporary glass architecture, gold accents, and timeless elegance with panoramic city vistas.', '["Infinity Pool","Gymnasium","Concierge","Sky Lounge","24/7 Security"]', '["Rooftop Infinity Sky Pool","Double-Height Grand Entrance Lobby","Zen Garden & Yoga Pavilion","Automated Smart Tower Parking"]', 'P51800000001', NULL, NULL, TRUE, TRUE, '2026-08-11T12:00:00.000Z', '2026-08-11T12:00:00.000Z'),
('Adani The Views', 'adani-the-views', 'Adani Realty', 'Residential', 'Mumbai', 'Pant Nagar, Ghatkopar East, Mumbai', '₹ 1.99 Cr Onwards', 19900000, 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80', '2, 3 & 4 BHK', 2, 4, 'Dec 2027', 'under-construction', 'Signature 200-ft Skywalk & Podium Living', 'Adani The Views in Pant Nagar, Ghatkopar East offers premium 2, 3 & 4 BHK residences featuring a signature 200-foot elevated skywalk, expansive podium gardens, and top-tier luxury amenities.', '["Skywalk","Clubhouse","Gymnasium","Swimming Pool","Kids Play Area"]', '["200-foot Signature Skywalk","Landscaped Podium Garden","Adani Realty Build Quality Assurance","10 Mins to Eastern Express Highway"]', 'P51900031165', NULL, NULL, TRUE, TRUE, '2026-08-11T12:00:00.000Z', '2026-08-11T12:00:00.000Z'),
('Orient Odyssey', 'orient-odyssey', 'Orient Corp', 'Residential', 'Mumbai', 'Ghatkopar East, Mumbai', '₹ 1.91 Cr Onwards', 19100000, 'https://images.unsplash.com/photo-1570129477492-45c003edd2be?w=1200&q=80', '1, 2, 3 & 4 BHK', 1, 4, 'Dec 2030', 'new-launch', 'Modern Twin-Tower Landmark in Ghatkopar', 'Orient Odyssey by Orient Corp offers thoughtfully designed 1, 2, 3 & 4 BHK residences across two high-rise towers in Ghatkopar East, delivering modern comfort and curated lifestyle amenities.', '["Gymnasium","Landscape Garden","Jogging Track","Yoga Deck","24/7 Security"]', '["2 Towers Spanning 0.36 Acres","Yoga & Meditation Sky Deck","Proximity to Ghatkopar Metro & Transit","Smart Space Layouts"]', 'PM1180002600214', NULL, NULL, TRUE, TRUE, '2026-08-11T12:00:00.000Z', '2026-08-11T12:00:00.000Z'),
('9 Anemone Heights', '9-anemone-heights', 'Anemone Homes LLP', 'Residential', 'Mumbai', '90 Feet Rd, Pant Nagar, Ghatkopar East, Mumbai', '₹ 1.85 Cr Onwards', 18500000, 'https://images.unsplash.com/photo-1613490900233-141c5560d75d?w=1200&q=80', '2 & 3 BHK', 2, 3, 'June 2027', 'under-construction', 'Rise Above The Skyline on 90 Feet Road', 'Rising in the heart of Ghatkopar on 90 Feet Road, 9 Anemone Heights by Anemone Homes LLP offers premium city-view 2 & 3 BHK residences with curated amenities, grand lobbies, and high-speed elevator access.', '["Multipurpose Studio","Banquet Hall","Wellness Hub","Business Zone","Terrace Screening"]', '["Terrace Screening Zone & Cabanas","7 High-speed Lifts per Tower","2,000 Sq.Ft. Grand Entrance Lobby","Wellness Hub & In-house Salon"]', 'P51800099999', NULL, NULL, TRUE, TRUE, '2026-08-11T12:00:00.000Z', '2026-08-11T12:00:00.000Z'),
('House of Hiranandani Chembur', 'house-of-hiranandani-chembur', 'House of Hiranandani', 'Residential', 'Mumbai', 'Central Avenue, Chembur, Mumbai', '₹ 2.65 Cr Onwards', 26500000, 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?w=1200&q=80', '2, 3 & 4 BHK', 2, 4, 'Dec 2028', 'ultra-luxury', 'Signature Neo-Classical Elegance in Chembur', 'House of Hiranandani Chembur brings signature Neo-Classical architecture, expansive open greenery, and timeless luxury residences to Chembur. Featuring majestic archways, classical pillars, world-class amenities, and strategic connectivity to BKC and South Mumbai.', '["Swimming Pool","Gymnasium","Clubhouse","Tennis Court","Squash Court","Banquet Hall","Children''s Play Area"]', '["Signature Neo-Classical Architecture","Lush European Landscaped Gardens","Grand Clubhouse & Swimming Pool","5 Mins to BKC Connector & Eastern Freeway","Double-Height Classical Entrance Lobby"]', 'P51800032541', NULL, NULL, TRUE, TRUE, '2026-08-11T12:00:00.000Z', '2026-08-11T12:00:00.000Z'),
('Rustomjee Balmoral Golf Links', 'rustomjee-balmoral-golf-links', 'Rustomjee Group', 'Residential', 'Mumbai', 'Golf Link Enclave, Chembur, Mumbai', '₹ 3.45 Cr Onwards', 34500000, 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80', '3, 4 & 5 BHK', 3, 5, 'June 2028', 'ultra-luxury', 'Palatial Golf-Facing Residences in Chembur', 'Rustomjee Balmoral Golf Links presents an unrepeatable luxury living experience overlooking panoramic golf course greens. Featuring private elevator foyers, expansive wrap-around sundecks, white-glove concierge, and a rooftop sky lounge.', '["Golf Simulator","Infinity Pool","Sky Lounge","Private Theater","Fitness Center","Spa & Wellness Pavilion","Concierge Service"]', '["Unobstructed Golf Course Views","Private Elevator Foyers for Every Residence","Rooftop Infinity Pool & Sky Lounge","Exclusive Cigar & Wine Pavilion","Designed by Renowned International Architects"]', 'P51800048920', NULL, NULL, TRUE, TRUE, '2026-08-11T12:00:00.000Z', '2026-08-11T12:00:00.000Z');